  return _.fromPairs(map(function(row) {
    var t = row.slice(0, row.length - 1), p = row[row.length - 1];
    return [keyOf(t), {t: t, v: p >= 1 ? yes : coin(p)}];
  }, rows));
};

var lineitem_facts = relationOfFacts(lpFacts['lineitem/13'] || []);

var lineitem = lineitem_facts;

var instances_discounted = [].concat(
  // discounted(O,L) :- lineitem(O,L,_,_,Qty,Disc,_,_,Ship,_,_,_,_), Ship >= 19940101, Ship < 19950101, Disc >= 5, Disc =< 7, Qty < 24.
  (function() {
    return _.flatten(map(function(e1) {
      var O = e1.t[0];
      var L = e1.t[1];
      var Qty = e1.t[4];
      var Disc = e1.t[5];
      var Ship = e1.t[8];
