                return [];
              }
            } else {
              return [];
            }
          } else {
            return [];
          }
        } else {
          return [];
        }
      } else {
        return [];
      }
    }, _.values(lineitem)));
  })()
);
var discounted = relation({}, instances_discounted);

var instances_q6 = [].concat(
  // q6 :- discounted(_,_).
  (function() {
    return _.flatten(map(function(e1) {
      return [['q6', [], e1.v]];
    }, _.values(discounted)));
  })()
);
var q6 = relation({}, instances_q6);

// component 0 bool
var model = function() {
  return [holds(q6, [])()];
};
Infer({method: 'enumerate'}, model);

